#include <stdio.h>

int main(void) {
    int a = 1;
    int *p, q;            // p is an int *, but q is a plain int!
    p = &a;
    q = &a;
    printf("%d %d\n", *p, q);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a = 99;
    int *ptr = &a;      // ptr holds the address of a

    printf("a           = %d\n", a);
    printf("&a          = %p\n", (void *) &a);
    printf("ptr         = %p\n", (void *) ptr);
    printf("*ptr        = %d\n", *ptr);
    printf("&ptr        = %p\n", (void *) &ptr);
    printf("sizeof(ptr) = %zu\n", sizeof(ptr));
    return 0;
}

// ptr1.c

#include <stdio.h>

int main(void) {
    int a = 99;
    int *ptr = &a;        // ptr refers to a
    int b = *ptr + 1;     // b = a + 1

    printf("a = %d\n", a);
    printf("b = %d\n", b);

    return 0;
}

// ptr2.c

#include <stdio.h>

int main(void) {
    int a = 99;
    int *ptr = &a;        // ptr refers to a
    *ptr = -33;           // assigns -33 to a

    printf("a = %d\n", a);

    return 0;
}

#include <stdio.h>

int main(void) {
    int x = 10;
    int y = 20;
    int *p = &x;
    int *q = &y;

    printf("1: %d %d\n", *p, *q);

    p = q;            // copy the ADDRESS: p now points at y too
    printf("2: %d %d\n", *p, *q);

    *p = 7;           // writes 7 into y
    printf("3: x = %d, y = %d\n", x, y);

    q = &x;
    *q = *p + 1;      // x = y + 1
    printf("4: x = %d, y = %d\n", x, y);
    return 0;
}

#include <stdio.h>
#include <stddef.h>

int main(void) {
    int a = 5;
    int *ptr = NULL;      // points at no object

    if (ptr == NULL) {
        puts("ptr is NULL: do not use *ptr");
    }

    ptr = &a;
    if (ptr != NULL) {
        printf("*ptr = %d\n", *ptr);
    }
    return 0;
}

