#include <stdio.h>

// makes *x the smaller and *y the larger of the two values
void minfirst(int *x, int *y) {
    if (*x > *y) {
        int tmp = *x;
        *x = *y;
        *y = tmp;
    }
}

int main(void) {
    int a = 9;
    int b = 4;
    minfirst(&a, &b);
    printf("a = %d, b = %d\n", a, b);
    minfirst(&a, &b);
    printf("a = %d, b = %d\n", a, b);
    return 0;
}

