#include <stdio.h>

// moves each value one place to the right: a gets c's old value,
// b gets a's old value, c gets b's old value
void rotate(int *a, int *b, int *c) {
    int tmp = *c;
    *c = *b;
    *b = *a;
    *a = tmp;
}

int main(void) {
    int x = 1;
    int y = 2;
    int z = 3;
    rotate(&x, &y, &z);
    printf("%d %d %d\n", x, y, z);
    rotate(&x, &y, &z);
    printf("%d %d %d\n", x, y, z);
    return 0;
}
